document.addEventListener("DOMContentLoaded",(function(){const toggleBtn=document.getElementById("theme-toggle"),themeIcon=document.getElementById("theme-icon"),logo=document.getElementById("logo"),toggleBtnSideNav=document.getElementById("theme-toggle-side-nav"),themeIconSideNav=document.getElementById("theme-icon-side-nav"),labelSideNav=document.getElementById("label-side-nav"),icons={light:"images/icon_sun.svg",dark:"images/icon_moon.svg"},iconsSideNav={light:"url('/images/icon_sun.svg')",dark:"url('/images/icon_moon.svg')"},labels={light:"Light",dark:"Dark"},logos={light:"images/Light_logo.svg",dark:"images/Dark_logo.svg"};function applyTheme(theme){document.body.setAttribute("data-theme",theme),localStorage.setItem("theme",theme),themeIcon&&(themeIcon.src=icons[theme]),logo&&(logo.src=logos[theme]),themeIconSideNav&&themeIconSideNav.style.setProperty("--icon-url",iconsSideNav[theme]),labelSideNav&&(labelSideNav.textContent=labels[theme])}const savedTheme=localStorage.getItem("theme")||"dark";applyTheme(savedTheme),toggleBtn&&toggleBtn.addEventListener("click",()=>{const current=document.body.getAttribute("data-theme");applyTheme("dark"===current?"light":"dark")}),toggleBtnSideNav&&toggleBtnSideNav.addEventListener("click",()=>{const current=document.body.getAttribute("data-theme");applyTheme("dark"===current?"light":"dark")})}));